fn main() {
    {
        let greeting = String::from("hello");
        println!("{greeting}");
    } // greeting goes out of scope here and its memory is freed
    println!("done");
}

fn main() {
    let a = String::from("crab");
    let b = a;              // ownership moves from a to b
    // println!("{a}");     // error: borrow of moved value: `a`
    println!("{b}");
}

fn shout(text: String) -> String {
    text.to_uppercase()   // makes a new String and returns it
}   // text goes out of scope here and is dropped

fn main() {
    let word = String::from("hi");
    let loud = shout(word);   // word moves into shout
    // println!("{word}");    // error: borrow of moved value: `word`
    println!("{loud}");
}

